import{_ as n,a0 as a,w as r,s as l,ao as d,I as s,x as o,a1 as p,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"Linux有问必答：Linux上如何查看某个进程的线程 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有问必答：Linux上如何查看某个进程的线程 | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有问必答：Linux上如何查看某个进程的线程 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有问必答：Linux上如何查看某个进程的线程 | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150518 Linux FAQs with Answers--How to view threads of a process on Linux","title":"Linux有问必答：Linux上如何查看某个进程的线程","tag":"201506","desc":""},"relativePath":"201506/20150518 Linux FAQs with Answers--How to view threads of a process on Linux.md","filePath":"[post].md"}'),u={name:"201506/20150518 Linux FAQs with Answers--How to view threads of a process on Linux.md"};function x(m,t,f,h,L,c){const e=a("Link");return r(),l("div",null,[t[13]||(t[13]=d(`<h1 id="linux有问必答-linux上如何查看某个进程的线程" tabindex="-1">Linux有问必答：Linux上如何查看某个进程的线程 <a class="header-anchor" href="#linux有问必答-linux上如何查看某个进程的线程" aria-label="Permalink to “Linux有问必答：Linux上如何查看某个进程的线程”">​</a></h1><blockquote><p><strong>问题</strong>： 我的程序在其内部创建并执行了多个线程，我怎样才能在该程序创建线程后监控其中单个线程？我想要看到带有它们名称的单个线程详细情况（如，CPU/内存使用率）。</p></blockquote><p>线程是现代操作系统上进行并行执行的一个流行的编程方面的抽象概念。当一个程序内有多个线程被叉分出用以执行多个流时，这些线程就会在它们之间共享特定的资源（如，内存地址空间、打开的文件），以使叉分开销最小化，并避免大量高成本的IPC（进程间通信）通道。这些功能让线程在并发执行时成为一个高效的机制。</p><p>在Linux中，程序中创建的线程（也称为轻量级进程，LWP）会具有和程序的PID相同的“线程组ID”。然后，各个线程会获得其自身的线程ID（TID）。对于Linux内核调度器而言，线程不过是恰好共享特定资源的标准的进程而已。经典的命令行工具，如ps或top，都可以用来显示线程级别的信息，只是默认情况下它们显示进程级别的信息。</p><p>这里提供了<strong>在Linux上显示某个进程的线程</strong>的几种方式。</p><h3 id="方法一-ps" tabindex="-1">方法一：PS <a class="header-anchor" href="#方法一-ps" aria-label="Permalink to “方法一：PS”">​</a></h3><p>在ps命令中，“-T”选项可以开启线程查看。下面的命令列出了由进程号为&lt;pid&gt;的进程创建的所有线程。</p><pre><code>$ ps -T -p &lt;pid&gt;
</code></pre><p><img src="https://farm8.staticflickr.com/7749/17350561110_94cacfc456_c.jpg" alt=""></p><p>“SID”栏表示线程ID，而“CMD”栏则显示了线程名称。</p><h3 id="方法二-top" tabindex="-1">方法二： Top <a class="header-anchor" href="#方法二-top" aria-label="Permalink to “方法二： Top”">​</a></h3><p>top命令可以实时显示各个线程情况。要在top输出中开启线程查看，请调用top命令的“-H”选项，该选项会列出所有Linux线程。在top运行时，你也可以通过按“H”键将线程查看模式切换为开或关。</p><pre><code>$ top -H
</code></pre><p><img src="https://farm9.staticflickr.com/8824/17350561070_3dfe447974_c.jpg" alt=""></p><p>要让top输出某个特定进程&lt;pid&gt;并检查该进程内运行的线程状况：</p><pre><code>$ top -H -p &lt;pid&gt;
</code></pre><p><img src="https://farm8.staticflickr.com/7797/17538002751_c8a3d574d8_c.jpg" alt=""></p><h3 id="方法三-htop" tabindex="-1">方法三： Htop <a class="header-anchor" href="#方法三-htop" aria-label="Permalink to “方法三： Htop”">​</a></h3><p>一个对用户更加友好的方式是，通过htop查看单个进程的线程，它是一个基于ncurses的交互进程查看器。该程序允许你在树状视图中监控单个独立线程。</p><p>要在htop中启用线程查看，请开启htop，然后按<code>&lt;F2&gt;</code>来进入htop的设置菜单。选择“设置”栏下面的“显示选项”，然后开启“树状视图”和“显示自定义线程名”选项。按<code>&lt;F10&gt;</code>退出设置。</p><p><img src="https://farm6.staticflickr.com/5338/17350364568_59bce22e7b_b.jpg" alt=""></p><p>现在，你就会看到下面这样单个进程的线程视图。</p><p><img src="https://farm9.staticflickr.com/8885/17350560930_98952d5350_c.jpg" alt=""></p><hr>`,24)),s("p",null,[t[1]||(t[1]=o("via: ",-1)),p(e,{href:"http://ask.xmodulo.com/view-threads-process-linux.html"},{default:i(()=>[...t[0]||(t[0]=[o("http://ask.xmodulo.com/view-threads-process-linux.html",-1)])]),_:1})]),s("p",null,[t[5]||(t[5]=o("作者：",-1)),p(e,{href:"http://ask.xmodulo.com/author/nanni"},{default:i(()=>[...t[2]||(t[2]=[o("Dan Nanni",-1)])]),_:1}),t[6]||(t[6]=o(" 译者：",-1)),p(e,{href:"https://github.com/GOLinux"},{default:i(()=>[...t[3]||(t[3]=[o("GOLinux",-1)])]),_:1}),t[7]||(t[7]=o(" 校对：",-1)),p(e,{href:"https://github.com/wxy"},{default:i(()=>[...t[4]||(t[4]=[o("wxy",-1)])]),_:1})]),s("p",null,[t[10]||(t[10]=o("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[8]||(t[8]=[o("LCTT",-1)])]),_:1}),t[11]||(t[11]=o(" 原创翻译，",-1)),p(e,{href:"https://linux.cn/"},{default:i(()=>[...t[9]||(t[9]=[o("Linux中国",-1)])]),_:1}),t[12]||(t[12]=o(" 荣誉推出",-1))])])}const w=n(u,[["render",x]]);export{_ as __pageData,w as default};
